override fun <T : String?> locate(
    queryBuilder: QueryBuilder,
    expr: Expression<T>,
    substring: String
) = queryBuilder {
    append("LOCATE(\\'", substring, "\\',", expr, ")")
}

private class MATCH(val expr: Expression<*>, val pattern: String, val mode: MatchMode) : Op<Boolean>() {
    override fun toQueryBuilder(queryBuilder: QueryBuilder) = queryBuilder {
        append("MATCH(", expr, ") AGAINST ('", pattern, "' ", mode.mode(), ")")
    }
}

override fun <T> jsonExtract(
    expression: Expression<T>,
    vararg path: String,
    toScalar: Boolean,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) = queryBuilder {
    if (toScalar) append("JSON_UNQUOTE(")
    append("JSON_EXTRACT(", expression, ", ")
    path.ifEmpty { arrayOf("") }.appendTo { +"\"$$it\"" }
    append(")${if (toScalar) ")" else ""}")
}

override fun jsonContains(
    target: Expression<*>,
    candidate: Expression<*>,
    path: String?,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) = queryBuilder {
    append("JSON_CONTAINS(", target, ", ", candidate)
    path?.let {
        append(", '$$it'")
    }
    append(")")
}

override fun jsonExists(
    expression: Expression<*>,
    vararg path: String,
    optional: String?,
    jsonType: IColumnType<*>,
    queryBuilder: QueryBuilder
) {
    val oneOrAll = optional?.lowercase()
    if (oneOrAll != "one" && oneOrAll != "all") {
        TransactionManager.current().throwUnsupportedException("MySQL requires a single optional argument: 'one' or 'all'")
    }
    queryBuilder {
        append("JSON_CONTAINS_PATH(", expression, ", ")
        append("'$oneOrAll', ")
        path.ifEmpty { arrayOf("") }.appendTo { +"'$$it'" }
        append(")")
    }
}

open fun concat(separator: String, queryBuilder: QueryBuilder, vararg expr: Expression<*>): Unit = queryBuilder {
    if (separator == "") {
        append("CONCAT(")
    } else {
        append("CONCAT_WS('", separator, "',")
    }
    expr.appendTo { +it }
    append(")")
}

/**
 * SQL function that concatenates strings from a group into a single string.
 *
 * @param expr Group concat options.
 * @param queryBuilder Query builder to append the SQL function to.
 */
open fun <T : String?> groupConcat(expr: GroupConcat<T>, queryBuilder: QueryBuilder): Unit = queryBuilder {
    append("GROUP_CONCAT(")
    if (expr.distinct) {
        append("DISTINCT ")
    }
    append(expr.expr)
    if (expr.orderBy.isNotEmpty()) {
        append(" ORDER BY ")
        expr.orderBy.appendTo { (expression, sortOrder) ->
            currentDialect.dataTypeProvider.precessOrderByClause(this, expression, sortOrder)
        }
    }
    expr.separator?.let {
        append(" SEPARATOR '$it'")
    }
    append(")")
}
